/* Loads seed.json (the rows the app was designed with) into an empty store, plus a demo owner account. Generated by Chakram. */
import { randomUUID } from 'node:crypto';
import seed from './seed.json' with { type: 'json' };
import { entityNames, type EntityName } from './schema.js';
import { hashPassword } from './auth.js';
import type { Store } from './store.js';

export const DEMO_ORG = process.env.DEFAULT_ORG_ID || 'org-1';

export async function seedIfEmpty(store: Store): Promise<void> {
  await store.ensureOrg(DEMO_ORG, process.env.DEFAULT_ORG_NAME || 'Default');
  const email = process.env.SEED_OWNER_EMAIL || 'owner@example.com';
  if (!(await store.findUserByEmail(email))) {
    const password = process.env.SEED_OWNER_PASSWORD || 'change-me-now';
    await store.createUser({ id: randomUUID(), orgId: DEMO_ORG, email, name: 'Owner', passwordHash: hashPassword(password), role: 'owner' });
    console.log(`[api] created owner ${email} (password from SEED_OWNER_PASSWORD)`);
  }
  for (const name of entityNames) {
    if ((await store.count(name, DEMO_ORG)) > 0) continue;
    const rows = (seed as Record<string, Record<string, unknown>[]>)[name] ?? [];
    for (const row of rows) await store.create(name as EntityName, DEMO_ORG, row);
    if (rows.length) console.log(`[api] seeded ${rows.length} ${name} rows`);
  }
}
